// 原型与宿主 JSON 同源；原型更新流程是受控状态示意，不连接网络、不安装程序。
(() => {
  const locales=window.IEDITOR_RESOURCES, palettes=window.IEDITOR_PALETTES;
  const flat=(obj,prefix='',result={})=>{for(const [key,value] of Object.entries(obj)){const path=prefix?prefix+'.'+key:key;if(value&&typeof value==='object')flat(value,path,result);else result[path]=value;}return result;};
  const source=flat(locales['zh-CN']); const inverse=new Map(Object.entries(source).map(([key,value])=>[value,key]));
  const aliases={'1 寸':'1寸','2 寸':'2寸','小 2 寸':'小2寸','工作台 /':'工作台 /','原图对比（按住）':'原图对比','图像工作台':'智能图像工作台'};
  let state={language:'zh-CN',mode:'Light',palette:'DotNet'},update='idle';
  try { state={...state,...JSON.parse(localStorage.getItem('ieditor.prototype')||'{}')}; } catch {}
  if(new URLSearchParams(location.search).has('capture'))document.body.dataset.capture='true';
  const t=key=>flat(locales[state.language])[key]??source[key]??key;
  const key=short=>'Localization.'+short;
  function renderQuality(){const status=document.querySelector('#stFmt'),quality=document.querySelector('#qRange');if(!status||!quality)return;const format=document.querySelector('#fmtSeg .on')?.dataset.value?.toUpperCase()||'JPG';const size=Math.round(Number(quality.value)*0.94);status.textContent=t(key('PhotoStudio.Summary.FormatQuality')).replace('{0}',format).replace('{1}',quality.value).replace('{2}',t(key('PhotoStudio.Summary.ApproximateSize')).replace('{0:0}',size));}
  document.querySelector('#qRange')?.addEventListener('input',renderQuality);
  document.querySelector('#fmtSeg')?.addEventListener('segchange',renderQuality);
  const nodes=[],attrs=[];
  function register(root){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:node=>node.parentElement?.closest('script,style,svg')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});let node;while(node=walker.nextNode()){const original=node.textContent,trimmed=original.trim(),normalized=aliases[trimmed]??trimmed;const resource=inverse.get(normalized);if(resource)nodes.push({node,resource,before:original.slice(0,original.indexOf(trimmed)),after:original.slice(original.indexOf(trimmed)+trimmed.length)});}root.querySelectorAll('[title],[placeholder]').forEach(el=>['title','placeholder'].forEach(attribute=>{const resource=inverse.get(el.getAttribute(attribute));if(resource)attrs.push({el,attribute,resource});}));}
  const tools=document.createElement('div');tools.className='product-tools';tools.innerHTML='<button data-theme-cycle class="title-icon" type="button"></button><div class="title-palette-swatches"></div><div class="language-picker"><button data-language-open class="title-icon" aria-haspopup="menu" aria-expanded="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 5h12M9 3v2m4 0c-1 6-5 10-10 12m2-9c2 4 4 6 8 8m1 5 4-11 4 11m-7-3h6"/></svg></button><div class="title-language-menu" role="menu" hidden><button data-culture="zh-CN" role="menuitem"></button><button data-culture="en-US" role="menuitem"></button></div></div>';
  document.querySelector('.titlebar')?.insertBefore(tools,document.querySelector('.win-controls'));
  const workspaceWindow=document.querySelector('.window'),windowRestore=document.createElement('button');windowRestore.type='button';windowRestore.dataset.windowRestore='';windowRestore.hidden=true;windowRestore.textContent='IEditor';document.body.append(windowRestore);
  const captionButtons=[...document.querySelectorAll('.titlebar .win-controls > button')];
  if(captionButtons.length!==3)throw Error('The desktop caption must contain exactly three direct buttons');
  captionButtons.forEach((button,index)=>{button.dataset.windowAction=['minimize','maximize','close'][index];button.onclick=()=>{if(index===1)workspaceWindow.classList.toggle('prototype-maximized');else{workspaceWindow.hidden=true;workspaceWindow.dataset.windowState=index===0?'minimized':'closed';windowRestore.hidden=false;}};});
  windowRestore.onclick=()=>{workspaceWindow.hidden=false;delete workspaceWindow.dataset.windowState;windowRestore.hidden=true;};
  tools.querySelector('[data-theme-cycle]').onclick=()=>{const modes=['System','Light','Dark'];set({mode:modes[(modes.indexOf(state.mode)+1)%3]});};
  const languageMenu=tools.querySelector('.title-language-menu'),languageButton=tools.querySelector('[data-language-open]');
  languageButton.onclick=event=>{event.stopPropagation();languageMenu.hidden=!languageMenu.hidden;languageButton.setAttribute('aria-expanded',!languageMenu.hidden);};
  tools.querySelectorAll('[data-culture]').forEach(button=>button.onclick=()=>{languageMenu.hidden=true;languageButton.setAttribute('aria-expanded','false');set({language:button.dataset.culture});});
  document.addEventListener('click',event=>{if(!event.target.closest('.language-picker')){languageMenu.hidden=true;languageButton.setAttribute('aria-expanded','false');}});
  document.addEventListener('keydown',event=>{if(event.key==='Escape'){languageMenu.hidden=true;languageButton.setAttribute('aria-expanded','false');}});
  for(const palette of Object.keys(palettes)){const button=document.createElement('button');button.type='button';button.dataset.paletteKey=palette;button.style.setProperty('--swatch',palettes[palette].Light.StudioAccentColor);button.onclick=()=>set({palette});tools.querySelector('.title-palette-swatches').append(button);}
  const swatches=document.querySelector('[data-palettes]');if(swatches)for(const palette of Object.keys(palettes)){const button=document.createElement('button');button.type='button';button.className='swatch';button.dataset.paletteKey=palette;button.style.background=palettes[palette].Light.StudioAccentColor;button.addEventListener('click',()=>set({palette}));swatches.append(button);}
  document.addEventListener('segchange',event=>{if(['light','dark','system'].includes(event.detail.value))set({mode:event.detail.value[0].toUpperCase()+event.detail.value.slice(1)});});
  document.querySelectorAll('.menu-entry').forEach(entry=>{const text=entry.textContent.trim();if(text.includes('关于 IEditor')){entry.classList.remove('disabled');entry.addEventListener('click',event=>{event.preventDefault();about.showModal();});}if(text.includes('检查更新'))entry.addEventListener('click',event=>{event.preventDefault();about.showModal();advance();});});
  const about=document.createElement('dialog');about.className='product-about';about.innerHTML=`<header class="about-titlebar"><b data-i18n="About.Text.Title"></b><div><button data-about-min>−</button><button data-about-max>□</button><button class="about-close" data-close>×</button></div></header><div class="about-heading"><img src="../logo.png" alt="IEditor"><div><h2>IEditor</h2><div data-i18n="About.Text.Description"></div></div></div><dl class="about-meta"><dt data-i18n="About.Text.Version"></dt><dd>v0.3.8</dd><dt data-i18n="About.Text.CompileTime"></dt><dd>2026-10-15 00:00:00</dd><dt data-i18n="About.Text.Platform"></dt><dd>.NET 10 · Avalonia 12.1.4</dd><dt data-i18n="About.Text.Author"></dt><dd>dotnet9</dd></dl><a href="https://github.com/dotnet9/IEditor" class="btn" data-i18n="About.Text.Repository"></a><div class="about-update"><p data-i18n="About.Text.UpdateDescription"></p><button class="btn primary" data-update-action></button><button class="btn" data-update-cancel data-i18n="About.Text.Cancel" hidden></button><p role="status" data-update-status></p></div><p data-i18n="About.Text.Copyright"></p>`;document.body.append(about);about.querySelector('[data-close]').onclick=()=>about.close();about.querySelector('[data-about-min]').onclick=()=>about.close();about.querySelector('[data-about-max]').onclick=()=>about.classList.toggle('about-maximized');about.querySelector('[data-update-action]').onclick=advance;about.querySelector('[data-update-cancel]').onclick=()=>{update='canceled';renderUpdate();};
  function advance(){update=({idle:'checking',checking:'available',available:'downloading',downloading:'downloaded',downloaded:'installed',installed:'checking',canceled:'checking',failed:'checking'})[update];renderUpdate();}
  function renderUpdate(){const labels={idle:'Check',checking:'Checking',available:'Download',downloading:'Downloading',downloaded:'Install',installed:'Check',canceled:'Check',failed:'Check'};about.querySelector('[data-update-action]').textContent=t(key('About.Text.'+labels[update]));about.querySelector('[data-update-cancel]').hidden=!['checking','downloading'].includes(update);about.querySelector('[data-update-status]').textContent=update==='idle'?'':update==='installed'?t(key('About.Text.Downloaded')):t(key('About.Text.'+({checking:'Checking',available:'Available',downloading:'Downloading',downloaded:'Downloaded',canceled:'Canceled',failed:'Failed'})[update])).replace('{0}','0.3.8');}
  function set(change){Object.assign(state,change);localStorage.setItem('ieditor.prototype',JSON.stringify(state));render();}
  function render(){const dark=state.mode==='Dark'||(state.mode==='System'&&matchMedia('(prefers-color-scheme: dark)').matches);const token=palettes[state.palette][dark?'Dark':'Light'];const css={'--bg':'StudioBackgroundColor','--surface':'StudioSurfaceColor','--surface-2':'StudioRaisedColor','--border':'StudioBorderColor','--border-strong':'StudioBorderColor','--text-1':'StudioTextColor','--text-2':'StudioMutedColor','--text-3':'StudioMutedColor','--primary':'StudioAccentColor','--cyan':'StudioSecondaryColor'};for(const [name,value]of Object.entries(css))document.documentElement.style.setProperty(name,token[value]);document.documentElement.style.setProperty('--grad',`linear-gradient(135deg,${token.StudioAccentColor},${token.StudioSecondaryColor})`);document.body.dataset.theme=dark?'dark':'light';document.documentElement.lang=state.language;
    for(const item of nodes)item.node.textContent=item.before+t(item.resource)+item.after;for(const item of attrs)item.el.setAttribute(item.attribute,t(item.resource));document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(key(el.dataset.i18n)));
    const modeButton=tools.querySelector('[data-theme-cycle]');modeButton.textContent=({System:'▣',Light:'☀',Dark:'☾'})[state.mode];modeButton.dataset.mode=state.mode;modeButton.title=t(key('Settings.Labels.Theme'))+': '+t(key('Common.Theme.'+state.mode));modeButton.setAttribute('aria-label',modeButton.title);
    const captionLabels=state.language==='zh-CN'?['最小化','最大化或还原','关闭']:['Minimize','Maximize or restore','Close'];captionButtons.forEach((button,index)=>{button.title=captionLabels[index];button.setAttribute('aria-label',button.title);});
    languageButton.title=t(key('Settings.Labels.Language'));languageButton.setAttribute('aria-label',languageButton.title);tools.querySelectorAll('[data-culture]').forEach(button=>{button.textContent=t(key('Common.Language.'+(button.dataset.culture==='zh-CN'?'SimplifiedChinese':'English')));button.setAttribute('aria-checked',button.dataset.culture===state.language);});
    document.querySelectorAll('[data-palette-key]').forEach(button=>{button.classList.toggle('on',button.dataset.paletteKey===state.palette);button.title=t(key('Settings.Options.'+button.dataset.paletteKey));});renderQuality();renderUpdate();}
  register(document.body);render();
  matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>render());
  window.IEditorPrototype={set,getState:()=>({...state}),openAbout:()=>about.showModal(),setUpdate:value=>{update=value;renderUpdate();}};
})();
